/** Every reason a run may warn with. The union is the whole vocabulary. */
export type WarnReason =
  | "gate-retry"
  | "qa-review-missing"
  | "worktree-left-dirty";

export interface RunWarnEvent {
  kind: "warn";
  reason: WarnReason;
  detail: string;
}

export function warnEvent(reason: WarnReason, detail: string): RunWarnEvent {
  return { kind: "warn", reason, detail };
}

