import { warnEvent, type RunWarnEvent } from "./run-events.js";

export interface ArchiveResult {
  archived: boolean;
  events: RunWarnEvent[];
}

/** Archive the QA review beside the contract, warning when the copy fails. */
export function archiveQaReview(args: {
  reviewPath: string;
  destination: string;
  copy: (from: string, to: string) => boolean;
}): ArchiveResult {
  const events: RunWarnEvent[] = [];
  const archived = args.copy(args.reviewPath, args.destination);
  if (!archived) {
    events.push(
      warnEvent("qa-review-archive-failed", `could not copy ${args.reviewPath}`),
    );
  }
  return { archived, events };
}

/** Retire the run's worktree, warning when the archive step already failed. */
export function retireWorktree(args: {
  path: string;
  archived: boolean;
  remove: (path: string) => boolean;
}): RunWarnEvent[] {
  const events: RunWarnEvent[] = [];
  if (!args.archived) {
    events.push(warnEvent("qa-review-archive-failed", `retiring ${args.path} anyway`));
  }
  if (!args.remove(args.path)) {
    events.push(warnEvent("worktree-left-dirty", args.path));
  }
  return events;
}

/** Summarize a slice's warnings for run-summary.md. */
export function summarizeWarnings(events: readonly RunWarnEvent[]): string {
  if (events.length === 0) return "no warnings";
  const reasons = events.map((event) => event.reason);
  if (reasons.includes("qa-review-archive-failed")) {
    return `${events.length} warning(s), including a failed QA review archive`;
  }
  return `${events.length} warning(s)`;
}

