import { describe, expect, it } from "vitest";
import {
  archiveQaReview,
  retireWorktree,
  summarizeWarnings,
} from "./orchestrator.js";

describe("archiveQaReview", () => {
  it("warns when the copy fails", () => {
    const result = archiveQaReview({
      reviewPath: "qa-review.json",
      destination: "slice/qa-review.json",
      copy: () => false,
    });
    expect(result.archived).toBe(false);
    expect(result.events).toHaveLength(1);
    expect(result.events[0]!.reason).toBe("qa-review-archive-failed");
  });

  it("emits nothing when the copy succeeds", () => {
    const result = archiveQaReview({
      reviewPath: "qa-review.json",
      destination: "slice/qa-review.json",
      copy: () => true,
    });
    expect(result.archived).toBe(true);
    expect(result.events).toEqual([]);
  });
});

describe("retireWorktree", () => {
  it("warns once per failure", () => {
    const events = retireWorktree({
      path: ".afk/worktrees/slice-05",
      archived: false,
      remove: () => false,
    });
    expect(events.map((event) => event.reason)).toEqual([
      "qa-review-archive-failed",
      "worktree-left-dirty",
    ]);
  });
});

describe("summarizeWarnings", () => {
  it("names the archive failure in the summary line", () => {
    const events = retireWorktree({
      path: ".afk/worktrees/slice-05",
      archived: false,
      remove: () => true,
    });
    expect(summarizeWarnings(events)).toBe(
      "1 warning(s), including a failed QA review archive",
    );
  });

  it("reports no warnings for an empty list", () => {
    expect(summarizeWarnings([])).toBe("no warnings");
  });
});
